extends Node
var p
func _ready() -> void:
	p = get_meta("viento_project")
	_probe()
func _snapshot(label: String, details: Dictionary = {}) -> void:
	var host = p.host.get_ref()
	print("VIENTO_BUDGET_SNAPSHOT:" + JSON.stringify({"label": label, "used": host.execution_budget.snapshot(), "details": details}))
func _probe() -> void:
	var host = p.host.get_ref()
	p.subscribe_event("queue", _receive)
	var accepted := 0
	for index in range(65):
		if p.publish_event("queue", true):
			accepted += 1
	_snapshot("rejected", {"accepted": accepted, "pending": host.event_bus.pending_count(), "sequence": host.event_bus.sequence})
func _receive(_value) -> bool:
	return true
